options.css:
@ {
	white-space: nowrap;
}@ 
DIV.TitleLevel2
{
	border-bottom: 1px solid #A0A5A8;
	margin: 10px 0px 10px 0px;
	position: relative;
	vertical-align: bottom;
	width: 100%;
}@ 
DIV.TitleLevel2 H2
{
	padding-left: 5px;
	padding-top: 3px;	
	background-color: #737A7E;
	display: inline;
	color: white;
	font-size: 11px;
	font-weight: bold;
	padding-right: 5px;
}@ 
DIV.Panel_Tab_Content DIV.TitleLevel2 H2
{
	background-color: #456b8c;
	color: white;
}@ 
TR.CheckList_ListHeader,@  TR.list_header
{
	background-color: #727a7e;
	color: White;
	border-collapse: collapse;
}@ 
TD.CheckList_ListHeader
{
	padding-left: 5px;
}@ 
TD.list_header_text
{
	border: 1px solid White;
	padding: 0px 2px 0px 2px;
	border-collapse: collapse;
}@ 
TD.list_header_text A
{
	color: White;
	text-decoration: none;
}@ 
A.list_header_link
{
	color: White;
	text-decoration: none;
}@ 
A.list_header_link:hover
{
	text-decoration: underline;
}@ 
TR.CheckList_ListItem,@  TR.edr-L1
{
	background-color: #E8E9EB !important;
}@ 
TR.edr-L1,@  TR.edr-L2
{
	padding: 2px !important;
}@ 
TR.edr-L1 TD A,@  TR.edr-L2 TD A
{
	color: #000000;
	text-decoration: none;
}@ 
TR.edr-L1 TD SPAN.Browsebutton A,@  TR.edr-L2 TD SPAN.Browsebutton A
{
	color:white; 
	text-decoration:none;
}@ 
TD.list_text
{
	border: 1px solid White;
	padding: 0px 2px 0px 2px;
	height: 25px;
}@ 
TD.list_textInteger
{
	border: 1px solid White;
	padding: 0px 2px 0px 2px;
	height: 25px;
	text-align: right;
}@ 
TD.list_textHidden
{
	display: none;
}@ 
TR.list_textHidden
{
	display: none;
	height: 0px;
}@ 
TR.CheckList_ListItemAlternate,@  TR.edr-L2
{
	background-color: #E8E9EB !important;
}@  
TABLE.simulationTableSub{
	padding-bottom: 10px;
}@

@ .Conversation_Warning_Text
{
background: #F6B221;
margin-bottom: 10px;
height: 25px;
display: flex;
align-items: center;
justify-content: center;
}@ 

.Conversation_Warning_Button
{
    padding-left: 4px;
    padding-right: 4px;
    margin: 7px !important;
    margin-bottom: 7px !important;
    height: 20px;
    display: flex;
    justify-content: center;
    align-items: center;
}@ 

.Conversation_Warning_Button > span
{
    height: 25px;
    padding : inherit;
    font-size: 11px;
}@
